#!/bin/bash
# This file was generated from bin/completion/templates/cds-tmpl.sh by
# 'cds completion --generate' and is written to bin/completion/scripts/cds.sh.
#
# Do not edit directly — modify the template and regenerate.
#
# Completion strategy (fastest-first):
#   1. Shortcuts    — single-character aliases resolved before any other logic.
#   2. Top-level    — all known subcommands when no subcommand has been typed yet.
#   3. Flags        — matched when the current token starts with '-'.
#   3.5. Option values  — static values for known flags (e.g. --to sqlite).
#   3.6. Comma values   — comma-separable list (e.g. cds add ai,hana).
#   4. File positionals — files/dirs for subcommands that take a path argument.
#   4.6. String positionals — fixed word list (e.g. cds help <tab>).
#   5. Dynamic fallback — calls 'cds completion' for anything not covered above.
#
# compopt -o nospace suppresses the trailing space bash normally appends after a
# completion, which is required for path completions (so the user can keep typing
# a subdirectory) and for flag names (so '=' can follow immediately).
CDS_COMMAND="cds"

_completeCds()
{
    local current previous cmd
    COMPREPLY=()
    current="${COMP_WORDS[COMP_CWORD]}"
    previous="${COMP_WORDS[COMP_CWORD - 1]}"
    # The subcommand is always the second token (index 1).
    cmd="${COMP_WORDS[1]}"
    # Step 1: resolve single-character shortcuts to their canonical command name
    # so that subsequent case statements only need to handle canonical names.
{{SHORTCUT_CASE}}
    # Step 2: top-level — offer all known subcommands when no subcommand has been
    # typed yet (COMP_WORDS includes the command itself, so ≤ 2 means "cds <cursor>").
    if [[ "${#COMP_WORDS[@]}" -le 2 ]]; then
        COMPREPLY=( $(compgen -W "{{COMMANDS}}" -- "$current") )
        compopt -o nospace
        return 0
    fi

    # Step 3: flag/option completion — only triggered when the token starts with '-'.
    if [[ "$current" == -* ]]; then
        case "$cmd" in
{{FLAG_CASES}}
        esac
        if [[ "${#COMPREPLY[@]}" -gt 0 ]]; then
            compopt -o nospace
            return 0
        fi
    fi

    # Step 3.5: option-value completion — triggered when the previous word is a known option.
    case "$cmd" in
{{OPTION_VALUE_CASES}}
    esac

    # Step 3.6: comma-separated option-value completion.
    # Splits $current on commas, filters out already-used values, prepends the prefix.
    case "$cmd" in
{{COMMA_CASES}}
    esac

    # Step 4: file-sentinel positionals — fill COMPREPLY with files and return.
    case "$cmd" in
{{FILE_CASES}}
    esac
    if [[ "${#COMPREPLY[@]}" -gt 0 ]]; then
        compopt -o nospace
        return 0
    fi

    # Step 4.6: string positionals (e.g. cds help <tab>).
    case "$cmd" in
{{STRING_POSITIONAL_CASES}}
    esac
    if [[ "${#COMPREPLY[@]}" -gt 0 ]]; then
        compopt -o nospace
        return 0
    fi

    # Step 5: dynamic fallback — calls 'cds completion' for subcommands whose arguments
    # cannot be determined statically (e.g. service names, model names, unknown flags).
    # Single-quoting $previous/$current prevents bare word 'h' from being interpreted
    # as the 'help' shortcut by the completion handler before it is processed.
    local options
    options=$($CDS_COMMAND completion --shell bash --prev "'$previous'" --curr "'$current'" --line "'${COMP_WORDS[*]}'")
    COMPREPLY=( $(compgen -W "${options}" -- "${current}") )
    compopt -o nospace
    return 0
}

# Register the completion function for the 'cds' command.
complete -F _completeCds "$CDS_COMMAND"
